import {
  AllCSSProperties,
  ComponentChildren,
  JSX,
  TargetedEvent,
} from "preact";
import { TFunction } from "../localization";
import { InternalDialogCloseEvent } from "./core/dialog";
import Icon from "./icon";

export type QrArtComponentProps = {
  channelName: string;
  channelLogo?: string;
  amountText: string;
  qr: ComponentChildren;
  merchantName: string;
  t: TFunction;
  nmid?: string;
};

export function hasCustomQrArt(channelCode: string): boolean {
  return getCustomQrArtComponent(channelCode) !== null;
}

export function getCustomQrArtComponent(
  channelCode: string,
): JSX.ElementType<QrArtComponentProps> | null {
  if (channelCode === "QRIS") {
    return QrArtQris;
  }

  if (channelCode === "SGQR") {
    return QrArtPaynow;
    // return QrArtSgqr;
  }

  if (channelCode === "DUITNOW_QR") {
    return QrArtDuitnow;
  }

  if (channelCode === "PROMPTPAY") {
    return QrArtPromptPay;
  }

  return null;
}

function QrArtQris(props: QrArtComponentProps) {
  return (
    <div>
      {hardcodedGraphics.closeButton({ top: "12px", right: "12px" })}
      <QrMinicardQris {...props} />
    </div>
  );
}

function QrMinicardQris(props: QrArtComponentProps) {
  const { merchantName, amountText, nmid } = props;

  const qrisAccentColor = "#DB4848";
  const padding = 120;
  const width = 960;
  const height = 1290;
  const innerWidth = width - 120 * 2;

  const logoRowY = 60;
  const textRowY = 270;
  const qrY = 440;

  const logoRowMargin = 80;
  const logoRowHeight = 120;
  const qrMargin = 33;

  const triangle1Size = 350;
  const triangle1X = -180;
  const triangle1Y = 340;

  const triangle2Size = 500;
  const triangle2X = width - triangle2Size / 2;
  const triangle2Y = height - triangle2Size / 2 + 70;

  function rectRotateAroundCenter(
    angle: number,
    x: number,
    y: number,
    width: number,
    height: number,
  ) {
    return `rotate(${angle}, ${x + width / 2}, ${y + height / 2})`;
  }

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      style={{ aspectRatio: width / height }}
    >
      {/* background triangles */}
      <rect
        fill={qrisAccentColor}
        x={triangle1X}
        y={triangle1Y}
        width={triangle1Size}
        height={triangle1Size}
        transform={rectRotateAroundCenter(
          45,
          triangle1X,
          triangle1Y,
          triangle1Size,
          triangle1Size,
        )}
      />
      <rect
        fill={qrisAccentColor}
        x={triangle2X}
        y={triangle2Y}
        width={triangle2Size}
        height={triangle2Size}
        transform={rectRotateAroundCenter(
          -128,
          triangle2X,
          triangle2Y,
          triangle2Size,
          triangle2Size,
        )}
      />
      {/* header row */}
      <foreignObject
        x={logoRowMargin}
        y={logoRowY}
        width={width - logoRowMargin * 2}
        height={logoRowHeight}
      >
        <div
          style={{
            height: "100%",
            position: "relative",
          }}
        >
          {/* logos baselines should be aligned, qris logo height should be as tall as the bird's head */}
          {hardcodedGraphics.qris({
            position: "absolute",
            left: "0",
            bottom: "0px",
            height: "auto",
            width: "60%",
          })}
          {hardcodedGraphics.gpn({
            position: "absolute",
            right: "0",
            top: "0",
            height: "100%",
            width: "auto",
          })}
        </div>
      </foreignObject>
      {/* merchant name and nmid */}
      <foreignObject
        x={padding}
        y={textRowY}
        width={innerWidth}
        height="90"
        style={{ overflow: "visible" }}
      >
        <div
          style={{
            color: "black",
            fontSize: "37px",
            textAlign: "center",
            height: "100%",
            lineHeight: "37px",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "center",
            fontFamily: "Nunito Regular, var(--xendit-font-family)",
          }}
        >
          <div
            className="xendit-text-semibold"
            style={{ whiteSpace: "nowrap", width: "100%" }}
          >
            <div
              style={{
                overflow: "hidden",
                textOverflow: "ellipsis",
                margin: "0 -48px",
              }}
            >
              {merchantName.toUpperCase()}
            </div>
          </div>
          <div
            className="xendit-text-semibold"
            style={{ fontSize: "50px", lineHeight: "70px" }}
          >
            {amountText}
          </div>
          {nmid ? (
            <div
              style={{
                fontSize: "30px",
                lineHeight: "30px",
                marginTop: "20px",
              }}
            >
              NMID: {nmid}
            </div>
          ) : null}
        </div>
      </foreignObject>
      {/* white background for qr */}
      <rect
        x={padding - qrMargin}
        y={qrY - qrMargin}
        width={innerWidth + qrMargin * 2}
        height={innerWidth + qrMargin * 2}
        fill="white"
      />
      {/* qr image */}
      <foreignObject x={padding} y={qrY} width={innerWidth} height={innerWidth}>
        <div style={{ "--xendit-qr-foreground-color": "black" }}>
          {props.qr}
        </div>
      </foreignObject>
    </svg>
  );
}

